const products = [
  { name: 'Keyboard', price: 60, inStock: true },
  { name: 'Monitor', price: 220, inStock: false },
  { name: 'Mouse', price: 25, inStock: true }
];

// filter: keep only in-stock products
const available = products.filter(function (product) {
  return product.inStock === true;
});
console.log(available);
// [{ name: 'Keyboard', ... }, { name: 'Mouse', ... }]

// map: transform each product into just its name
const productNames = products.map(product => product.name);
console.log(productNames);
// ['Keyboard', 'Monitor', 'Mouse']

// chaining filter and map together
const availableNames = products
  .filter(product => product.inStock)
  .map(product => product.name);
console.log(availableNames);
// ['Keyboard', 'Mouse']

