sections.content:
Conditionals:
if (age >= 18) {
  console.log('Adult');
} else if (age >= 13) {
  console.log('Teenager');
} else {
  console.log('Child');
}

switch (day) {
  case 'Mon': console.log('Start of week'); break;
  case 'Fri': console.log('Almost weekend'); break;
  default: console.log('Midweek');
}

Loops:
for (let i = 0; i < 5; i++) {
  console.log(i); // 0, 1, 2, 3, 4
}

let count = 0;
while (count < 3) {
  console.log(count);
  count++;
}

const fruits = ['apple', 'banana', 'cherry'];
for (const fruit of fruits) {
  console.log(fruit); // iterates each value directly, no manual indexing needed
}

