sections.content:
Callbacks (the original pattern): a function passed as an argument, to be called later when an operation finishes.
setTimeout(function () {
  console.log('3 seconds passed');
}, 3000);

Promises: an object representing a value that will exist eventually, with three possible states (pending, fulfilled, rejected):
fetch('/api/data')
  .then(response => response.json())
  .then(data => console.log(data))
  .catch(error => console.error('Something went wrong:', error));

async/await: modern syntax that lets asynchronous code read almost like synchronous code, built on top of Promises:
async function loadData() {
  try {
    const response = await fetch('/api/data');
    const data = await response.json();
    console.log(data);
  } catch (error) {
    console.error('Something went wrong:', error);
  }
}

The await keyword pauses execution inside an async function until the awaited Promise resolves, without blocking the rest of the page — only that specific function's execution waits.

sections.code:
// Promise chain version
function loadUserAndPosts(userId) {
  fetch(`/api/users/${userId}`)
    .then(response => response.json())
    .then(user => {
      console.log('User:', user);
      return fetch(`/api/users/${userId}/posts`);
    })
    .then(response => response.json())
    .then(posts => {
      console.log('Posts:', posts);
    })
    .catch(error => {
      console.error('Failed to load data:', error);
    });
}

// async/await version - same behavior, reads top-to-bottom
async function loadUserAndPostsAsync(userId) {
  try {
    const userResponse = await fetch(`/api/users/${userId}`);
    const user = await userResponse.json();
    console.log('User:', user);

    const postsResponse = await fetch(`/api/users/${userId}/posts`);
    const posts = await postsResponse.json();
    console.log('Posts:', posts);
  } catch (error) {
    console.error('Failed to load data:', error);
  }
}

