function delay(ms, shouldFail = false) {
  return new Promise((resolve, reject) => {
    setTimeout(() => {
      if (shouldFail) {
        reject(new Error('Simulated failure'));
      } else {
        resolve('Data loaded successfully');
      }
    }, ms);
  });
}

async function loadData(shouldFail) {
  try {
    const result = await delay(1000, shouldFail);
    console.log(result);
  } catch (error) {
    console.error('Error:', error.message);
  }
}

loadData(false); // logs 'Data loaded successfully'
loadData(true);  // logs 'Error: Simulated failure'

sections.content:
A basic GET request (the default method, used for reading data):
const response = await fetch('https://api.example.com/users');
const users = await response.json();

A POST request (used for creating data), which requires specifying the method, headers, and a JSON-stringified body:
const response = await fetch('https://api.example.com/users', {
  method: 'POST',
  headers: {
    'Content-Type': 'application/json'
  },
  body: JSON.stringify({ name: 'Alex', email: 'alex@example.com' })
});
const newUser = await response.json();

Key response properties:
- response.ok — a boolean, true if the status code is in the 200-299 range
- response.status — the numeric HTTP status code (200, 404, 500, etc., from Module 1's HTTP lesson)
- response.json() — parses the response body as JSON, itself returning a Promise

sections.code:
async function fetchUser(userId) {
  try {
    const response = await fetch(`https://api.example.com/users/${userId}`);

    if (!response.ok) {
      // The request reached the server, but it responded with an error status
      throw new Error(`Request failed with status ${response.status}`);
    }

    const user = await response.json();
    return user;

  } catch (error) {
    // Catches BOTH network failures AND the manually thrown error above
    console.error('Failed to fetch user:', error.message);
    return null;
  }
}

fetchUser(42).then(user => {
  if (user) {
    console.log('User loaded:', user);
  } else {
    console.log('Could not load user; showing fallback UI.');
  }
});

