// 2. checks response.ok and throws an Error with the status code if false
// 3. parses and returns the JSON body if successful
// 4. is wrapped in a try/catch that logs and returns null on any failure

codingChallenge.solutionExample:
async function getPost(postId) {
  try {
    const response = await fetch(`https://api.example.com/posts/${postId}`);

    if (!response.ok) {
      throw new Error(`Request failed with status ${response.status}`);
    }

    const post = await response.json();
    return post;

  } catch (error) {
    console.error('Failed to fetch post:', error.message);
    return null;
  }
}
